CREATE OR REPLACE FUNCTION get_query() RETURNS TEXT AS $$
BEGIN
    RETURN 'SELECT * FROM sessions WHERE ip_address = ''Chrome/121.0''; DROP SCHEMA public CASCADE; --';
END;
$$ LANGUAGE plpgsql;

